create unique index service_appointments_tenant_id on service_appointments(tenant_id,id);
create table appointment_reminders(id uuid primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,appointment_id uuid not null,actor_id int not null references users,minutes_before int not null check(minutes_before between 1 and 43200),run_at timestamptz not null,status text not null default 'pending' check(status in ('pending','sending','sent','blocked','check_required','cancelled')),detail text,created_at timestamptz not null default now(),sent_at timestamptz,foreign key(tenant_id,appointment_id) references service_appointments(tenant_id,id),unique(tenant_id,appointment_id,minutes_before));
alter table appointment_reminders enable row level security;alter table appointment_reminders force row level security;
create policy tenant_iso on appointment_reminders using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int);
create trigger fk_guard before insert or update on appointment_reminders for each row execute function fk_guard('users','actor_id');
